// Monta payload factual — só dados do banco
return $input.all().map((item) => {
  const p = item.json;
  return {
    json: {
      product_id: p.id,
      classify_input: {
        title: p.title,
        price: Number(p.price),
        original_price: p.original_price != null ? Number(p.original_price) : null,
        rating: p.rating != null ? Number(p.rating) : null,
        reviews: p.review_count != null ? Number(p.review_count) : null,
        sold: p.sold_count != null ? Number(p.sold_count) : null,
        category: p.category ?? 'unknown',
        avg_price_30d: p.avg_price_30d != null ? Number(p.avg_price_30d) : null,
        min_price_30d: p.min_price_30d != null ? Number(p.min_price_30d) : null,
        coupon_code: p.coupon_code ?? null,
        coupon_value: p.coupon_value != null ? Number(p.coupon_value) : null,
        coupon_type: p.coupon_type ?? null
      },
      affiliate_url: p.affiliate_url,
      image_url: p.image_url,
      source: p.source,
      opportunity_score: Number(p.opportunity_score)
    }
  };
});

const p = $json;
const input = $('Montar payload factual').item.json.classify_input;
const url = $('Montar payload factual').item.json.affiliate_url;

const priceFmt = Number(input.price).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const ratingLine = input.rating != null ? `⭐ ${String(input.rating).replace('.', ',')}/5` : null;
const soldLine = input.sold != null ? `🛒 +${Number(input.sold).toLocaleString('pt-BR')} vendidos` : null;
const couponLine = input.coupon_code ? `🏷️ Cupom: ${input.coupon_code}` : null;

let story = null;
if (input.min_price_30d != null && input.price <= input.min_price_30d) {
  story = '🔥 MENOR PREÇO REGISTRADO!';
} else if (input.avg_price_30d != null && input.price <= input.avg_price_30d * 0.75) {
  const avg = Number(input.avg_price_30d).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  story = `🔥 PREÇO MUITO ABAIXO DO HISTÓRICO\nMédia 30d: ${avg} → agora ${priceFmt}`;
}

const wa = [
  '🔥 ACHADINHO KIDS',
  input.title,
  story,
  ratingLine,
  soldLine,
  `💰 ${priceFmt}`,
  couponLine,
  `👉 PEGAR OFERTA\n${url}`
].filter(Boolean).join('\n');

const ig = [
  `🧸 Achadinho!`,
  input.title,
  story,
  `Por ${priceFmt} hoje.`,
  ratingLine,
  soldLine,
  couponLine,
  '#achadinhos #maternidade #kids #oferta'
].filter(Boolean).join('\n');

return [{ json: { ...p, content_whatsapp: wa, content_instagram: ig, affiliate_url: url } }];
